  ('zcrm_5797994000003281455', 'Slingshot', 'Slingshot', 'Jacob Dooley', 'Sanil', 'Slingshot offers an integrated business platform tailored for artists and creatives, automating financial tasks such as expense tracking, accounting, and tax management. The platform utilizes partnerships with financial institutions for secure fund management and payment processing, while also providing wellness benefits and concierge support.', 'HV Genesis', 'Financial Innovation', 'Fall 2025', NULL, 'Reached Out', 'Jacob Dooley', 'Rejected', 'Financial Innovation', NULL, NULL, '2025-10-09 06:54:45', '2026-01-05 14:52:58', '2026-01-05 14:52:58'),
  ('zcrm_5797994000003281498', 'Privacy Lock', 'Privacy Lock', 'Jacob Dooley', 'Rittner', 'The main product is a global privacy compliance solution that includes features such as data mapping, consent management, and automated access requests, designed to function without collecting or processing customer data. It employs technologies like data encryption and secure data storage to ensure compliance with privacy regulations across various jurisdictions.', 'HV Genesis', 'Financial Innovation', 'Fall 2025', NULL, 'Reached Out', 'Jacob Dooley', 'Rejected', 'Financial Innovation', NULL, NULL, '2025-10-09 07:02:17', '2026-01-05 14:52:58', '2026-01-05 14:52:58'),
  ('zcrm_5797994000003281533', 'OneHubPOS', 'OneHubPOS', 'Jacob Dooley', 'Satheesh', 'OneHubPOS offers a cloud-based point-of-sale system tailored for small businesses in the restaurant and retail sectors, integrating order management, inventory control, and payment processing into a single platform. The system utilizes Android-based software and supports various hardware integrations, facilitating features like online ordering and secure payment transactions.', 'HV Genesis', 'Financial Innovation', 'Fall 2025', NULL, 'Reached Out', 'Jacob Dooley', 'Rejected', 'Financial Innovation', NULL, NULL, '2025-10-09 07:12:06', '2026-01-05 14:52:58', '2026-01-05 14:52:58'),
  ('zcrm_5797994000003281568', 'Volta Circuit', 'Volta Circuit', 'Jacob Dooley', 'Melika', 'Volta Circuit offers a non-custodial multi-signature wallet that enables users to maintain complete control over their digital assets, featuring customizable governance and policy options. The platform is designed to be wallet-agnostic, supporting various key management systems and facilitating on-chain operations without dependence on third-party services.', 'HV Genesis', 'Financial Innovation', 'Fall 2025', NULL, 'Reached Out', 'Jacob Dooley', 'Rejected', 'Financial Innovation', NULL, NULL, '2025-10-09 07:18:48', '2026-01-05 14:52:58', '2026-01-05 14:52:58'),
  ('zcrm_5797994000003281603', 'Digsfact', 'Digsfact', 'Jacob Dooley', 'Nishant Tomar', 'DigsFact offers an AI-driven solution for remote property inspections that utilizes video and photo capture to provide real-time measurements and layouts with high accuracy. The technology incorporates computer vision to streamline the estimation process for claims, repairs, and renovations, enhancing operational efficiency and reducing costs.', 'HV Genesis', 'Financial Innovation', 'Fall 2025', NULL, 'Reached Out', 'Jacob Dooley', 'Rejected', 'Financial Innovation', NULL, NULL, '2025-10-09 07:23:15', '2026-01-05 14:52:58', '2026-01-05 14:52:58'),
  ('zcrm_5797994000003281654', 'FoxEyes', 'FoxEyes', 'Marina Rezhda', 'Min Seo', 'Developer of robotic equipment and automated parts designed to meet the critical demands of the modern medical industry. The company offers a full-support robot for pedicle screw surgery and spine endoscope surgery-supporting robot, enabling medical professionals to use safer and user-friendly robotic surgical equipment while performing their surgeries.', 'HV STEM', 'Manufacturing Technology', 'Fall 2025', NULL, 'Reached Out', 'Marina Rezhda', 'Source', NULL, NULL, NULL, '2025-10-11 07:06:47', '2025-10-11 07:06:47', NULL),
  ('zcrm_5797994000003281680', 'Monarcha', 'Monarcha', 'Marina Rezhda', 'James Spokes', 'Developer of an AI-powered geospatial platform designed to simplify spatial data analysis for logistics, real estate, urban planning, and environmental teams. The company offers natural language-driven spatial analysis, browser-based access to over 50 geospatial tools, and seamless integration with public and proprietary datasets, enabling professionals in data-intensive sectors to work with spatial data without relying on specialized GIS expertise.', 'HV STEM', 'Manufacturing Technology', 'Fall 2025', NULL, 'Reached Out', 'Marina Rezhda', 'Rejected', NULL, 'Founder Not Interested', 'Marina Rezhda', '2025-10-11 07:12:50', '2025-10-29 11:48:14', '2025-10-29 11:48:46'),
  ('zcrm_5797994000003281706', 'Journey Robotics', 'Journey Robotics', 'Marina Rezhda', 'Reeg Allen', 'Manufacturer of automated airport baggage-handling systems intended for logistics management. The company''s products employ autonomous robotic arms with vacuum and grip technology, machine-vision bag detection, compact drop-in design adaptable to existing baggage carousels, safety sensors to avoid human interference, and remote monitoring dashboards, enabling airports and airlines to reduce labor strain, improve worker safety, streamline baggage flow, and improve passenger experience.', 'HV STEM', 'Manufacturing Technology', 'Fall 2025', NULL, 'Reached Out', 'Marina Rezhda', 'Source', NULL, NULL, NULL, '2025-10-11 07:17:22', '2025-10-11 07:17:22', NULL),
  ('zcrm_5797994000003281721', 'Adagy Robotics', 'Adagy Robotics', 'Marina Rezhda', 'Rosalind Shinkle', 'Provider of remote intervention service intended to rescue robots when they fail. The company offers trained operators to take over and drive robots back to a stable state, enabling clients to help robots resume autonomous operation.', 'HV STEM', 'Manufacturing Technology', 'Fall 2025', NULL, 'Reached Out', 'Marina Rezhda', 'Source', NULL, NULL, NULL, '2025-10-11 07:20:14', '2025-10-11 07:20:14', NULL),
  ('zcrm_5797994000003281747', 'BoatBites', 'BoatBites', 'Marina Rezhda', 'John Bonaccorso', 'Developer of a B2B2C logistics platform designed to employ eco-friendly personal watercraft (PWCs) for on-demand food and beverage delivery, directly to boats and docks. The company''s B2B2C platform leverages a mobile app offering real-time ordering, GPS tracking, and seamless payments, enabling customers to connect through a nationwide network of marinas, vendors, and drivers, monetizing via transaction commissions and subscriptions, and has secured partnerships with national brands.', 'HV STEM', 'Manufacturing Technology', 'Fall 2025', NULL, 'Reached Out', 'Marina Rezhda', 'Source', NULL, NULL, NULL, '2025-10-11 07:23:39', '2025-10-11 07:23:39', NULL),
  ('zcrm_5797994000003281773', 'Flywheel AI', 'Flywheel AI', 'Marina Rezhda', 'Jash Mota', 'Developer of semi-autonomous excavators and a remote teleoperation platform designed to improve safety and productivity in industrial operations. The company offers automated machinery with advanced control systems and secure remote access, enabling contractors and industrial operators to manage equipment from any location, enhance precision, and increase operational efficiency.', 'HV STEM', 'Manufacturing Technology', 'Fall 2025', NULL, 'Reached Out', 'Marina Rezhda', 'Source', NULL, NULL, NULL, '2025-10-11 07:26:13', '2025-10-11 07:26:13', NULL),
  ('zcrm_5797994000003281787', 'Mandel AI', 'Mandel AI', 'Marina Rezhda', 'Nick Gospodinov', 'Developer of an AI-powered procurement platform designed for automating supply chain processes. The company''s platform offers features such as an autonomous request for quotations where AI contacts suppliers for quotes, automated data extraction that captures updates across supplier communication channels, proactive order monitoring with AI following up on order statuses, and auto-reconciliation to identify and resolve document discrepancies, enabling businesses to enhance efficiency, reduce errors, and improve visibility in their supply chain operations.', 'HV STEM', 'Manufacturing Technology', 'Fall 2025', NULL, 'Reached Out', 'Marina Rezhda', 'Source', NULL, NULL, NULL, '2025-10-11 07:29:28', '2025-10-11 07:29:28', NULL),
  ('zcrm_5797994000003281813', 'Moment Robotics', 'Moment Robotics', 'Marina Rezhda', 'Ben Berkowitz', 'Developer of robots designed to automate the movement of goods within hospitals. The company''s technology transports, places, and organizes supplies, samples, and equipment, helping hospital staff to focus on their patients.', 'HV STEM', 'Manufacturing Technology', 'Fall 2025', NULL, 'Reached Out', 'Marina Rezhda', 'Source', NULL, NULL, NULL, '2025-10-11 07:31:52', '2025-10-11 07:31:52', NULL),
  ('zcrm_5797994000003281839', 'TerraHaptix', 'TerraHaptix', 'Marina Rezhda', 'Maxwell Maduka', 'Operator of a robotics company intended to offer unmanned support systems for civic, military, surveillance, payload operations, and other core industries. The company provides security and surveillance drones, an autonomous operating system, and a stationary surveillance platform, enabling agriculture, energy, and security businesses to enhance efficiency, reduce risks, and provide valuable data for analysis.', 'HV STEM', 'Manufacturing Technology', 'Fall 2025', NULL, 'Reached Out', 'Marina Rezhda', 'Source', NULL, NULL, NULL, '2025-10-11 07:34:51', '2025-10-11 07:34:51', NULL),
  ('zcrm_5797994000003281865', 'TableFlow', 'TableFlow', 'Marina Rezhda', 'Eric Ciminelli', 'Developer of AI document processing software designed to automate the extraction and validation of structured data from complex, unstructured documents. The company''s platform incorporates multi-modal AI combining computer vision and natural language processing, zero-shot learning for adaptability to varied document formats, real-time processing with confidence scoring, and contextual validation of extracted data, enabling enterprises in industries such as healthcare, finance, logistics, and legal to reduce manual effort, increase processing speed, and improve data accuracy.', 'HV STEM', 'Manufacturing Technology', 'Fall 2025', NULL, 'Reached Out', 'Marina Rezhda', 'Source', NULL, NULL, NULL, '2025-10-11 07:37:54', '2025-10-11 07:37:54', NULL),
