  ('zcrm_5797994000003284278', 'Chefee', 'Chefee', 'Marina Rezhda', 'Assaf Pashut', 'Developer of a robotics technology company intended to develop embedded robotic chefs. The company''s device robots are designed to perform specific tasks to assist or replace human labor in various settings, enabling the culinary industry with automation services.', 'HV STEM', 'Manufacturing Technology', 'Fall 2025', NULL, 'Reached Out', 'Marina Rezhda', 'Rejected', NULL, 'Founder Not Interested', 'Marina Rezhda', '2025-10-05 12:39:32', '2025-10-26 17:37:44', '2025-10-26 17:37:44'),
  ('zcrm_5797994000003284304', 'Clip Automation', 'Clip Automation', 'Marina Rezhda', 'Rajeev Bhalla', 'Developer of digital factory software designed to accelerate new product manufacturing. The company''s software offers powerful and critical insights into the manufacturing process along with automating the design workflow and consolidating information from all sources in one secure, organized, and easy-access workspace, enabling companies to reduce the time and effort required to launch a product.', 'HV STEM', 'Manufacturing Technology', 'Fall 2025', NULL, 'Reached Out', 'Marina Rezhda', 'Source', NULL, NULL, NULL, '2025-10-05 12:42:56', '2025-10-05 12:42:56', NULL),
  ('zcrm_5797994000003284330', 'Terran Robotics', 'Terran Robotics', 'Marina Rezhda', 'Zachary Dwiel', 'Provider of home construction services designed to specialize in automated adobe wall building. The company offers services that use artificial intelligence for three-dimensional print homes using a custom-designed cable-driven robot to emulate and improve upon traditional earthen building techniques with features such as fire-resistance and premium sound dampening, enabling clients to radically reduce the cost of housing, lower energy bills, and maintain environmentally friendly impact.', 'HV STEM', 'Manufacturing Technology', 'Fall 2025', NULL, 'Reached Out', 'Marina Rezhda', 'Source', NULL, NULL, NULL, '2025-10-05 12:45:49', '2025-10-05 12:45:49', NULL),
